(()=>{'use strict';
let activeLoader=window.zpfc_payment_loader||null;
let activeSubmitText='';
let isOpening=false;
const getAjaxUrl=()=>window.fluentcart_checkout_vars?.ajaxurl||'/wp-admin/admin-ajax.php';
const $t=(s)=>(window.fct_zoho_payments_data?.translations?.[s]||s);
const getBtnText=()=>{
  if(activeSubmitText)return activeSubmitText;
  const t=window.fluentcart_checkout_vars?.submit_button;
  return(typeof t==='string'&&t.trim())?t.trim():(t?.text||$t('Place Order'));
};
const postAjax=async(url,data)=>{
  const res=await fetch(url,{
    method:'POST',
    headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},
    credentials:'same-origin',
    body:new URLSearchParams(data)
  });
  try{return await res.json();}catch(_){throw new Error('Invalid server response');}
};
const resetLoader=(loader,msg='',type='error')=>{
  const l=loader||activeLoader||window.zpfc_payment_loader;
  const txt=getBtnText();
  try{l?.changeLoaderStatus?.('');}catch(_){}
  try{l?.hideLoader?.();}catch(_){}
  try{l?.showCheckoutButton?.();}catch(_){}
  try{l?.enableCheckoutButton?.(txt);}catch(_){}
  try{
    document.querySelectorAll('.fct-checkout-modal-loader,.fct-loading-wrapper,.fct-checkout-loader,.fluent-cart-checkout-loader,.fct-loader,[data-fct-loader],.el-loading-mask,.fluent-cart-loading,#fct_loading_payment_processor').forEach(el=>{
      el.style.display='none';
      el.setAttribute('aria-hidden','true');
    });
    document.querySelectorAll('.fct-loading,.loading,.fct-processing,.is-loading').forEach(el=>el.classList.remove('fct-loading','loading','fct-processing','is-loading'));
    document.querySelectorAll('.fct-checkout-button,[data-fct-submit-button],.fct-checkout-btn,button[type="submit"]').forEach(btn=>{
      btn.removeAttribute('disabled');
      btn.classList.remove('disabled','fct-btn-loading','loading','is-loading');
      btn.style.pointerEvents='auto';
      if(!btn.innerText||!btn.innerText.trim()||btn.innerText.toLowerCase().includes('processing')){
        btn.innerText=txt;
      }
    });
  }catch(_){}
  if(msg){
    console.warn('Zoho Payments:',msg);
    try{
      const toast=window.fluentCart?.toast||window.fluentcart?.toast||window.FluentCart?.toast;
      if(typeof toast==='function')toast({type:type,message:msg});
    }catch(_){}
  }
};
const checkStatus=async(r)=>{
  try{
    const res=await postAjax(r.ajax_url||getAjaxUrl(),{
      action:'zpfc_payment_status',
      transaction_id:r.transaction_uuid||'',
      _ajax_nonce:r.nonce||''
    });
    const dt=res?.data||{};
    if(res?.success&&dt.transaction_status==='succeeded'&&dt.redirect_url){
      return dt.redirect_url;
    }
  }catch(_){}
  return null;
};
const renderZohoEmbed=(container)=>{
  if(!container||container.dataset.hasCustomContent==='true')return;
  container.dataset.hasCustomContent='true';
  const icons={
    cards:'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>',
    upi:'<img width="24" height="24" src="https://img.icons8.com/color/48/bhim.png" alt="UPI" style="width:24px;height:24px;display:block;object-fit:contain;" />',
    netbanking:'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21h18"></path><path d="M3 10h18"></path><path d="M5 6l7-3 7 3"></path><path d="M4 10v11"></path><path d="M20 10v11"></path><path d="M8 14v3"></path><path d="M12 14v3"></path><path d="M16 14v3"></path></svg>',
    wallets:'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12V7H5a2 2 0 0 1 0-4h14v4"></path><path d="M3 5v14a2 2 0 0 0 2 2h16v-5"></path><path d="M18 12a2 2 0 0 0 0 4h4v-4Z"></path></svg>'
  };
  const methods=[
    {key:'upi',label:$t('UPI'),icon:icons.upi},
    {key:'cards',label:$t('Cards'),icon:icons.cards},
    {key:'netbanking',label:$t('Net Banking'),icon:icons.netbanking},
    {key:'wallets',label:$t('Wallets'),icon:icons.wallets}
  ];
  let html='<div class="zpfc-embed-card">';
  html+='<div class="zpfc-embed-header"><p class="zpfc-embed-subheading">'+$t('Available payment methods')+'</p></div>';
  html+='<div class="zpfc-embed-methods">';
  methods.forEach(m=>{
    html+='<div class="zpfc-method-item" title="'+m.label+'">';
    html+='<span class="zpfc-method-icon">'+m.icon+'</span>';
    html+='<span class="zpfc-method-name">'+m.label+'</span>';
    html+='</div>';
  });
  html+='</div>';
  html+='<style>'
    +'.zpfc-embed-card{padding:14px 16px;border:1px solid #e2e8f0;border-radius:8px;background:#f8fafc;margin:8px 0 12px;box-sizing:border-box;}'
    +'.zpfc-embed-header{text-align:center;margin-bottom:10px;}'
    +'.zpfc-embed-subheading{margin:0;font-size:12px;color:#64748b;font-weight:500;letter-spacing:0.2px;}'
    +'.zpfc-embed-methods{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;}'
    +'.zpfc-method-item{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:8px 14px;background:#ffffff;border:1px solid #e2e8f0;border-radius:8px;min-width:68px;transition:all 0.2s ease;cursor:default;box-sizing:border-box;}'
    +'.zpfc-method-item:hover{border-color:#226db4;box-shadow:0 2px 8px rgba(34,109,180,0.12);}'
    +'.zpfc-method-icon{display:flex;align-items:center;justify-content:center;color:#226db4;margin-bottom:4px;height:24px;}'
    +'.zpfc-method-icon svg, .zpfc-method-icon img{width:24px;height:24px;display:block;object-fit:contain;}'
    +'.zpfc-method-name{font-size:11px;font-weight:500;color:#334155;}'
    +'</style>';
  html+='</div>';
  container.innerHTML=html;
};
const displayEmbedError=(container,msg)=>{
  if(!container)return;
  container.innerHTML='<div style="color:#ef4444;background:#fef2f2;border:1px solid #fecaca;padding:10px 14px;border-radius:6px;font-size:13px;margin:8px 0;">'+(msg||$t('An error occurred while loading Zoho Payments.'))+'</div>';
};
const onLoad=ev=>{
  const detail=ev?.detail||{};
  const loader=detail.paymentLoader||detail.loader;
  if(detail.paymentLoader){
    activeLoader=detail.paymentLoader;
    window.zpfc_payment_loader=detail.paymentLoader;
  }else if(detail.loader){
    activeLoader=detail.loader;
    window.zpfc_payment_loader=detail.loader;
  }
  const t=window.fluentcart_checkout_vars?.submit_button;
  if(typeof t==='string'&&t.trim())activeSubmitText=t.trim();
  else if(t?.text)activeSubmitText=t.text;
  const container=document.querySelector('.fluent-cart-checkout_embed_payment_container_zoho_payments');
  const finish=()=>{
    if(container)renderZohoEmbed(container);
    if(loader&&typeof loader.enableCheckoutButton==='function'){
      loader.enableCheckoutButton(getBtnText());
    }
  };
  if(detail.paymentInfoUrl){
    fetch(detail.paymentInfoUrl,{
      method:'POST',
      headers:{
        'Content-Type':'application/json',
        'X-WP-Nonce':detail.nonce||''
      },
      credentials:'same-origin'
    }).then(async(res)=>{
      const data=await res.json().catch(()=>({}));
      if(data?.status==='failed'){
        displayEmbedError(container,data?.message);
        if(loader&&typeof loader.hideLoader==='function')loader.hideLoader();
        return;
      }
      finish();
    }).catch(()=>{
      finish();
    });
  }else{
    finish();
  }
};
window.addEventListener('fluent_cart_load_payments_zoho_payments',onLoad);
const onPay=async ev=>{
  if(isOpening)return;
  isOpening=true;
  let r=ev.detail?.response||{};
  const loader=ev.detail?.paymentLoader||ev.detail?.loader||activeLoader||window.zpfc_payment_loader;
  if(loader){
    activeLoader=loader;
    window.zpfc_payment_loader=loader;
  }
  if(r.response?.payments_session_id)r=r.response;
  const sid=r.payments_session_id||r.payment_session_id;
  const amt=r.amount;
  const key=r.api_key;
  const acc=r.account_id;
  if(!sid||amt==null){
    isOpening=false;
    return resetLoader(loader,'Zoho Payments session was not initialized.','error');
  }
  const fAmt=typeof amt==='number'?amt.toFixed(2):String(amt);
  if(!fAmt||!isFinite(Number(fAmt))||Number(fAmt)<=0){
    isOpening=false;
    return resetLoader(loader,'Zoho Payments received an invalid amount.','error');
  }
  if(!window.ZPayments){
    for(let i=0;i<30&&!window.ZPayments;i++)await new Promise(res=>setTimeout(res,100));
  }
  if(!window.ZPayments){
    isOpening=false;
    return resetLoader(loader,'Zoho Payments checkout widget failed to load. Please refresh the page.','error');
  }
  let widget;
  try{
    widget=new window.ZPayments({
      account_id:acc,
      domain:'IN',
      otherOptions:{
        api_key:key,
        ...(r.test_mode?{is_test_mode:true}:{})
      }
    });
  }catch(err){
    isOpening=false;
    console.error('ZPayments Init Error:',err);
    return resetLoader(loader,'Unable to initialize Zoho Payments checkout.','error');
  }
  try{
    try{loader?.changeLoaderStatus?.($t('Payment Modal is opening...'));}catch(_){}
    const opt={
      payments_session_id:sid,
      payment_session_id:sid,
      amount:fAmt,
      currency_code:'INR',
      currency_symbol:'₹',
      description:r.description||'',
      invoice_number:r.invoice_number||'',
      reference_number:r.reference_number||''
    };
    if(r.address&&(r.address.name||r.address.email||r.address.phone))opt.address=r.address;
    const res=await widget.requestPaymentMethod(opt);
    try{await widget.close();}catch(_){}
    const stat=String(res?.status||res?.payment_status||'').toLowerCase();
    const isClosed=res?.code==='widget_closed'||stat==='closed'||stat==='canceled'||stat==='cancelled';
    const pid=res?.payment_id||res?.payment?.payment_id||res?.payments?.[0]?.payment_id||'';
    const pmid=res?.payment_method_id||res?.payment?.payment_method_id||'';
    const sig=res?.signature||res?.payment?.signature||'';
    if(!isClosed&&(pid||stat==='succeeded'||stat==='success'||res?.payments_session_id||res?.payment_session_id)){
      try{
        loader?.changeLoaderStatus?.($t('Processing payment...'));
        const cf=await postAjax(r.ajax_url||getAjaxUrl(),{
          action:'zpfc_confirm_payment',
          transaction_id:r.transaction_uuid||'',
          payment_id:pid,
          payment_method_id:pmid,
          signature:sig,
          session_id:sid,
          _ajax_nonce:r.nonce||''
        });
        if(cf?.success&&cf.data?.redirect_url){
          try{loader?.hideLoader?.();}catch(_){}
          window.location.assign(cf.data.redirect_url);
          return;
        }
      }catch(ce){
        console.error('Confirmation error:',ce);
      }
    }
    if(isClosed){
      resetLoader(loader,'Payment was canceled. You can try again when ready.','info');
      return;
    }
    const rUrl=await checkStatus(r);
    if(rUrl){
      try{loader?.hideLoader?.();}catch(_){}
      window.location.assign(rUrl);
      return;
    }
    resetLoader(loader,'Payment is processing. Please check your order status or try again.','info');
  }catch(e){
    try{await widget?.close();}catch(_){}
    const es=String(e?.message||e?.error||e?.code||e||'').toLowerCase();
    const isCancel=e?.code==='widget_closed'||es.includes('closed')||es.includes('cancel')||es.includes('user_cancelled');
    const msg=isCancel?'Payment was canceled. You can try again when ready.':(e?.message||'Payment failed. Please try again.');
    resetLoader(loader,msg,isCancel?'info':'error');
  }finally{
    isOpening=false;
  }
};
window.addEventListener('fluent_cart_payment_next_action_zoho_payments',onPay);
})();